#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

static ll isqrt_ll(ll x) {
    ll r = (ll)sqrtl((long double)x);
    while (r * r > x) r--;
    while ((r + 1) * (r + 1) <= x) r++;
    return r;
}

int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        ll a, b;
        scanf("%lld %lld", &a, &b);
        ll s = a + b, r = isqrt_ll(s);
        // Cost with final strength k: k-1 upgrades plus ceil(a/k)+ceil(b/k) moves.
        auto f = [&](ll k) { return k - 1 + (a + k - 1) / k + (b + k - 1) / k; };
        ll best = min(f(r), f(r + 1));
        // Any k at least as good satisfies k^2 - (best+1)k + s <= 0.
        ll q = isqrt_ll((best + 1) * (best + 1) - 4 * s);
        ll lo = max(1LL, (best + 1 - q) / 2 - 1), hi = (best + 1 + q) / 2 + 2;
        for (ll k = lo; k < hi; k++) best = min(best, f(k));
        printf("%lld\n", best);
    }
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static long isqrt(long x) {
        long r = (long) Math.sqrt((double) x);
        while (r * r > x) r--;
        while ((r + 1) * (r + 1) <= x) r++;
        return r;
    }

    static long f(long k, long a, long b) {
        return k - 1 + (a + k - 1) / k + (b + k - 1) / k;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int t = nextInt();
        StringBuilder sb = new StringBuilder();
        while (t-- > 0) {
            long a = nextLong(), b = nextLong();
            long s = a + b, r = isqrt(s);
            long best = Math.min(f(r, a, b), f(r + 1, a, b));
            // Any k at least as good satisfies k^2 - (best+1)k + s <= 0.
            long q = isqrt((best + 1) * (best + 1) - 4 * s);
            long lo = Math.max(1, (best + 1 - q) / 2 - 1), hi = (best + 1 + q) / 2 + 2;
            for (long k = lo; k < hi; k++) best = Math.min(best, f(k, a, b));
            sb.append(best).append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"math"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func isqrt(x int64) int64 {
	r := int64(math.Sqrt(float64(x)))
	for r*r > x {
		r--
	}
	for (r+1)*(r+1) <= x {
		r++
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	t := int(nextInt())
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for ; t > 0; t-- {
		a, b := nextInt(), nextInt()
		s := a + b
		r := isqrt(s)
		// Cost with final strength k: k-1 upgrades plus ceil(a/k)+ceil(b/k) moves.
		f := func(k int64) int64 { return k - 1 + (a+k-1)/k + (b+k-1)/k }
		best := min(f(r), f(r+1))
		// Any k at least as good satisfies k^2 - (best+1)k + s <= 0.
		q := isqrt((best+1)*(best+1) - 4*s)
		lo, hi := max(1, (best+1-q)/2-1), (best+1+q)/2+2
		for k := lo; k < hi; k++ {
			best = min(best, f(k))
		}
		w.WriteString(strconv.FormatInt(best, 10) + "\n")
	}
}
